import * as THREE from 'three';
import {autoFitOrthographicBounds} from '../camera-fit.js';
import {PASS_START,PASS_PATTERNS} from './passing-model.js';
export function createPassingSession({view,zoneRoot=view?.root,player,model,poser,partnerId='athletic-turtle'}){
 if(!view||!zoneRoot||!player||!model||!poser)throw Error('Passing actors unavailable');
 const saved={position:player.position.clone(),quaternion:player.quaternion.clone(),scale:player.scale.clone(),modelPosition:model.position.clone(),modelQuaternion:model.quaternion.clone(),modelScale:model.scale.clone(),pose:poser.getState(),children:player.children.map(n=>[n,n.visible]),background:[view.schoolView?.gymView?.entry,zoneRoot.getObjectByName?.('sportsField.ball'),view.schoolView?.throwCourt?.root,zoneRoot.getObjectByName?.('sportsField.passing-entry'),zoneRoot.getObjectByName?.('sportsField.passing-label'),zoneRoot.getObjectByName?.('sportsField.passing-pad'),...(zoneRoot.children??[]).filter(n=>['athletic-turtle','athletic-rabbit'].includes(n.userData?.species)&&n.userData.species!==partnerId),zoneRoot.getObjectByName?.('learning.sports.approach')].filter(Boolean).map(n=>[n,n.visible])};const lease=view.acquireResidentActivity?.(partnerId);if(!lease)throw Error('Passing partner unavailable');let alive=true,lastPose=-1,anchors;
 function place(p){zoneRoot.updateWorldMatrix(true,false);const point=zoneRoot.localToWorld(new THREE.Vector3(p.x,.05,p.z));if(player.parent)player.parent.worldToLocal(point);player.position.copy(point);const q=zoneRoot.getWorldQuaternion(new THREE.Quaternion()).multiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0,1,0),Math.PI/2));if(player.parent)q.premultiply(player.parent.getWorldQuaternion(new THREE.Quaternion()).invert());player.quaternion.copy(q);}
 try{for(const[n]of saved.background)n.visible=false;player.scale.set(1,1,1);model.position.set(0,0,0);model.quaternion.identity();model.scale.set(1,1,1);for(const child of player.children)if(child!==model)child.visible=false;place(PASS_START);poser.setPose('chalk',1,0);player.updateWorldMatrix(true,true);
 const hand=model.localToWorld(new THREE.Vector3(...poser.getAnchors().rightHand).add(new THREE.Vector3(0,0,.28)));zoneRoot.worldToLocal(hand);const target=PASS_PATTERNS[0].turtle;lease.pose({...target,yaw:-Math.PI/2});lease.model.updateWorldMatrix(true,true);const parts=lease.model.userData.parts,left=parts['Hand.L'].getWorldPosition(new THREE.Vector3()),right=parts['Hand.R'].getWorldPosition(new THREE.Vector3()),mid=left.add(right).multiplyScalar(.5),front=new THREE.Vector3(0,0,.18).applyQuaternion(lease.model.getWorldQuaternion(new THREE.Quaternion()));mid.add(front);zoneRoot.worldToLocal(mid);anchors={player:{x:hand.x-PASS_START.x,y:hand.y,z:hand.z-PASS_START.z},turtle:{x:mid.x-target.x,y:mid.y,z:mid.z-target.z}};}catch(error){dispose();throw error;}
 function update(s,time=0,reduced=false){if(!alive)return;place(s.player);model.position.set(0,0,0);model.rotation.set(0,0,0);const amount=s.phase==='outbound'?Math.max(0,1-s.elapsed/.32):['aiming','turtle-held','return-flight','catching'].includes(s.phase)||s.owner==='player'?1:0;if(Math.abs(lastPose-amount)>1e-6){poser.setPose('chalk',amount,0);lastPose=amount;}lease.pose({...s.turtle,yaw:-Math.PI/2});player.updateWorldMatrix(true,true);}
 function dispose({restore=true}={}){if(!alive)return;alive=false;lease.release();if(!restore)return;player.position.copy(saved.position);player.quaternion.copy(saved.quaternion);player.scale.copy(saved.scale);model.position.copy(saved.modelPosition);model.quaternion.copy(saved.modelQuaternion);model.scale.copy(saved.modelScale);try{poser.setPose(saved.pose.name,saved.pose.amount,saved.pose.time);}finally{for(const[n,visible]of saved.background)n.visible=visible;for(const[child,visible]of saved.children)child.visible=visible;player.updateWorldMatrix(true,true);}}
 return{anchors,update,dispose,partnerId,turtleUUID:lease.model.uuid};
}
export function fitPassingCamera(camera,root,viewport,preview=null){root.updateWorldMatrix(true,false);camera.position.copy(root.localToWorld(new THREE.Vector3(0,8.4,12)));camera.up.set(0,1,0);camera.lookAt(root.localToWorld(new THREE.Vector3(0,1.3,3.75)));camera.updateMatrixWorld(true);const local=new THREE.Box3(new THREE.Vector3(-3.9,.01,2.25),new THREE.Vector3(4.1,3.9,5.65));for(const p of preview??[])local.expandByPoint(new THREE.Vector3(p.x,p.y+.22,p.z));const bounds=local.applyMatrix4(root.matrixWorld);autoFitOrthographicBounds({camera,worldBounds:bounds,viewport,paddingPx:{top:9,right:9,bottom:9,left:9}});camera.updateMatrixWorld(true);return bounds;}
